=== src/TutorFlow.Domain/Authorization/IAuthorizationPolicy.cs
namespace TutorFlow.Domain.Authorization;
public enum TipoRecurso
{
    Reglamento,
    DatosEstudiante,
    ProgramaEstudiantes,
    DatosCoordinador,
}
/// <summary>
/// Recurso a autorizar. <see cref="ProgramaId"/> es el programa del estudiante objetivo (resuelto desde el roster)
/// o el programa listado; nunca se toma de la pregunta ni del LLM. Un objetivo ausente del roster se deniega.
/// </summary>
public sealed record RecursoAcademico(TipoRecurso Tipo, string? Id = null, string? ProgramaId = null);
public sealed record DecisionAutorizacion(bool Permitido, string Motivo)
{
    public static DecisionAutorizacion Permitir() => new(true, "permitido");
    public static DecisionAutorizacion Denegar(string motivo) => new(false, motivo);
}
/// <summary>
/// Politica pura y determinista (SPEC 6.1). Solo depende del principal y del recurso; el LLM ni concede ni deniega.
/// </summary>
public interface IAuthorizationPolicy
{
    DecisionAutorizacion Authorize(PrincipalAcademico principal, RecursoAcademico recurso);
}
=== src/TutorFlow.Domain/Authorization/PrincipalAcademico.cs
namespace TutorFlow.Domain.Authorization;
/// <summary>Rol declarado y validado en L1 (SPEC 6.2).</summary>
public enum RolAcademico
{
    Estudiante,
    Coordinador,
}
/// <summary>
/// Principal inmutable construido por L1 (consistencia de identidad, no autenticacion; SPEC 6.5).
/// Su alcance es el id propio o los programas del coordinador. Nunca se deriva de la pregunta ni del LLM.
/// Refinado en T-02.
/// </summary>
public sealed record PrincipalAcademico
{
    public PrincipalAcademico(RolAcademico rol, string id, IEnumerable<string>? programasCoordinados = null)
    {
        ArgumentException.ThrowIfNullOrEmpty(id);
        Rol = rol;
        Id = id;
        ProgramasCoordinados = (programasCoordinados ?? Array.Empty<string>()).ToArray();
    }
    public RolAcademico Rol { get; }
    public string Id { get; }
    /// <summary>Programas coordinados (vacio para un estudiante).</summary>
    public IReadOnlyList<string> ProgramasCoordinados { get; }
}
=== src/TutorFlow.Application/Ports/IToolDispatcher.cs
using TutorFlow.Domain.Authorization;
namespace TutorFlow.Application.Ports;
public sealed record CitaDocumental(string Documento, string Seccion);
/// <summary>Resultado ya calculado por el dominio (JSON con formato invariante) y sus citas deterministas (SPEC 7.5).</summary>
public sealed record ResultadoHerramienta(
    string Contenido,
    IReadOnlyList<CitaDocumental> Citas,
    bool UsoDatosEstudiante,
    string? Objetivo);
/// <summary>
/// Unica via de ejecucion de herramientas para el bucle del LLM: L3 (herramienta expuesta) -> esquema -> L4
/// (IAuthorizationPolicy antes de leer) -> ejecucion. El principal lo aporta el servidor, jamas el LLM; una
/// denegacion lanza AccesoDenegadoException y aborta la peticion.
/// </summary>
public interface IToolDispatcher
{
    IReadOnlyList<ToolDefinition> HerramientasExpuestas(PrincipalAcademico principal);
    Task<ResultadoHerramienta> DespacharAsync(
        PrincipalAcademico principal,
        InvocacionPropuesta invocacion,
        CancellationToken ct);
}
=== src/TutorFlow.Application/Ports/Llm.cs
using System.Text.Json;
namespace TutorFlow.Application.Ports;
/// <summary>Definicion de herramienta que ve el LLM (esquema JSON de sus argumentos).</summary>
public sealed record ToolDefinition(string Nombre, string Descripcion, JsonElement EsquemaArgumentos);
/// <summary>Propuesta de invocacion hecha por el LLM. Es solo una propuesta: el despachador la valida y autoriza.</summary>
public sealed record InvocacionPropuesta(string? Id, string Nombre, JsonElement Argumentos);
public enum RolMensaje
{
    Usuario,
    Asistente,
    Herramienta,
}
public sealed record LlmMensaje(
    RolMensaje Rol,
    string Contenido,
    string? InvocacionId = null,
    string? NombreHerramienta = null);
public sealed record LlmRequest(
    string Sistema,
    IReadOnlyList<LlmMensaje> Mensajes,
    IReadOnlyList<ToolDefinition> Herramientas,
    int MaxTokens);
public sealed record UsoTokens(int Entrada, int Salida);
public sealed record LlmResponse(
    string Texto,
    IReadOnlyList<InvocacionPropuesta> Invocaciones,
    UsoTokens Uso);
/// <summary>Puerto del proveedor LLM. Su salida es texto o propuestas; nunca decide permisos.</summary>
public interface ILlmClient
{
    Task<LlmResponse> CompletarAsync(LlmRequest solicitud, CancellationToken ct);
}
public interface IEmbeddingClient
{
    Task<IReadOnlyList<float[]>> VectorizarAsync(IReadOnlyList<string> textos, CancellationToken ct);
}
